/**
 * Validates that a string parameter is not null or blank.
 *
 * @param paramName the name of the parameter (for error messages)
 * @param paramValue the value to validate
 * @throws TikaConfigException if the value is null or blank
 */
public static void mustNotBeEmpty(String paramName, String paramValue) throws TikaConfigException {
    if (StringUtils.isBlank(paramValue)) {
        throw new TikaConfigException("parameter '" + paramName + "' must be set in the config file");
    }
}
